{
  "root": "main_list",
  "state": {},
  "elements": {
    "main_list": {
      "type": "List",
      "props": {},
      "children": [
        "title_main",
        "intro_text",
        "criteria_heading",
        "criteria_intro_text",
        "criteria_list",
        "recommended_heading",
        "card_fujifilm",
        "card_sony",
        "card_om_system",
        "table_heading",
        "specs_table",
        "quick_actions_heading",
        "quick_action_list",
        "sources_heading",
        "source_fujifilm",
        "source_sony",
        "source_om_system"
      ]
    },
    "title_main": {
      "type": "Text",
      "props": {
        "text": "Top Travel Mirrorless Recommendations",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "For a travel photographer needing portability without sacrificing stability, the best options released between 2020 and 2023 are the Fujifilm X-S20, Sony a6700, and OM System OM-5. These models specifically address your need for In-Body Image Stabilization (IBIS) in a chassis under 500g, while offering distinct advantages in lens ecosystems and color science."
      },
      "children": []
    },
    "criteria_heading": {
      "type": "Text",
      "props": {
        "text": "Criteria and Pricing Context",
        "variant": "h2"
      },
      "children": []
    },
    "criteria_intro_text": {
      "type": "Text",
      "props": {
        "text": "The recommendations below adhere strictly to your budget cap of $1,500 USD and weight limit of 500g (body including battery). Prices listed are approximate body-only retail prices as of late 2023/early 2024."
      },
      "children": []
    },
    "criteria_list": {
      "type": "List",
      "props": {},
      "children": [
        "criteria_weight",
        "criteria_lens",
        "criteria_ibis"
      ]
    },
    "criteria_weight": {
      "type": "List",
      "props": {},
      "children": [
        "icon_weight",
        "text_weight"
      ]
    },
    "icon_weight": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000175_01_6_feather.svg"
      },
      "children": []
    },
    "text_weight": {
      "type": "Text",
      "props": {
        "text": "Weight: Includes battery and memory card to reflect real-world travel load."
      },
      "children": []
    },
    "criteria_lens": {
      "type": "List",
      "props": {},
      "children": [
        "icon_lens",
        "text_lens"
      ]
    },
    "icon_lens": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000175_01_1_camera.svg"
      },
      "children": []
    },
    "text_lens": {
      "type": "Text",
      "props": {
        "text": "Lens Ecosystem: \"Affordable\" is defined by the availability of third-party options (Sigma, Tamron) or a mature Micro Four Thirds market."
      },
      "children": []
    },
    "criteria_ibis": {
      "type": "List",
      "props": {},
      "children": [
        "icon_ibis",
        "text_ibis"
      ]
    },
    "icon_ibis": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000175_01_7_activity.svg"
      },
      "children": []
    },
    "text_ibis": {
      "type": "Text",
      "props": {
        "text": "IBIS: All selected models feature 5-axis in-body stabilization, essential for handheld travel shots in low light or video."
      },
      "children": []
    },
    "recommended_heading": {
      "type": "Text",
      "props": {
        "text": "Recommended Models",
        "variant": "h2"
      },
      "children": []
    },
    "card_fujifilm": {
      "type": "Card",
      "props": {},
      "children": [
        "image_fujifilm",
        "text_fujifilm",
        "button_fujifilm"
      ]
    },
    "image_fujifilm": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000175_01_3_fujifilm_camera.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "text_fujifilm": {
      "type": "Text",
      "props": {
        "text": "Option 1: Fujifilm X-S20 | Best for color science and battery life | 7-stop IBIS",
        "variant": "h3"
      },
      "children": []
    },
    "button_fujifilm": {
      "type": "Button",
      "props": {
        "label": "View X-S20 Specs"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://fujifilm-x.com/global/products/cameras/x-s20/"
          }
        }
      },
      "children": []
    },
    "card_sony": {
      "type": "Card",
      "props": {},
      "children": [
        "image_sony",
        "text_sony",
        "button_sony"
      ]
    },
    "image_sony": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000175_01_4_sony_alpha_camera.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "text_sony": {
      "type": "Text",
      "props": {
        "text": "Option 2: Sony a6700 | Best for autofocus and lens selection | AI-driven Subject Tracking",
        "variant": "h3"
      },
      "children": []
    },
    "button_sony": {
      "type": "Button",
      "props": {
        "label": "View a6700 Details"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://electronics.sony.com/imaging/interchangeable-lens-cameras/aps-c/p/ilce6700-b"
          }
        }
      },
      "children": []
    },
    "card_om_system": {
      "type": "Card",
      "props": {},
      "children": [
        "image_om_system",
        "text_om_system",
        "button_om_system"
      ]
    },
    "image_om_system": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000175_01_5_nature_photography_camera.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "text_om_system": {
      "type": "Text",
      "props": {
        "text": "Option 3: OM System OM-5 | Best for durability and compactness | IP53 Weather Sealing",
        "variant": "h3"
      },
      "children": []
    },
    "button_om_system": {
      "type": "Button",
      "props": {
        "label": "View OM-5 Features"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://explore.omsystem.com/us/en/om-5"
          }
        }
      },
      "children": []
    },
    "table_heading": {
      "type": "Text",
      "props": {
        "text": "Technical Specifications Table",
        "variant": "h2"
      },
      "children": []
    },
    "specs_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "feature",
            "label": "Feature"
          },
          {
            "key": "fujifilm",
            "label": "Fujifilm X-S20"
          },
          {
            "key": "sony",
            "label": "Sony a6700"
          },
          {
            "key": "om_system",
            "label": "OM System OM-5"
          }
        ],
        "rows": [
          {
            "feature": "Release Year",
            "fujifilm": "May 2023",
            "sony": "July 2023",
            "om_system": "Oct 2022"
          },
          {
            "feature": "Sensor Size",
            "fujifilm": "APS-C (26MP)",
            "sony": "APS-C (26MP)",
            "om_system": "Micro 4/3 (20MP)"
          },
          {
            "feature": "Weight (Body)",
            "fujifilm": "~491g",
            "sony": "~493g",
            "om_system": "~414g"
          },
          {
            "feature": "Est. Price",
            "fujifilm": "~$1,299",
            "sony": "~$1,398",
            "om_system": "~$1,199"
          },
          {
            "feature": "Lens Mount",
            "fujifilm": "Fuji X Mount",
            "sony": "Sony E-Mount",
            "om_system": "Micro Four Thirds"
          },
          {
            "feature": "IBIS Rating",
            "fujifilm": "Up to 7.0 stops",
            "sony": "Up to 5.0 stops",
            "om_system": "Up to 7.5 stops"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_action_list": {
      "type": "List",
      "props": {},
      "children": [
        "button_compare_sensors",
        "button_search_lenses"
      ]
    },
    "button_compare_sensors": {
      "type": "Button",
      "props": {
        "label": "Compare Sensor Sizes"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.dpreview.com/articles/8670169226/sensor-sizes-explained"
          }
        }
      },
      "children": []
    },
    "button_search_lenses": {
      "type": "Button",
      "props": {
        "label": "Search Used Lenses"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.mpb.com/en-us"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "source_fujifilm": {
      "type": "Text",
      "props": {
        "text": "1. Fujifilm X-S20 Official Specifications"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://fujifilm-x.com/global/products/cameras/x-s20/specifications/"
          }
        }
      },
      "children": []
    },
    "source_sony": {
      "type": "Text",
      "props": {
        "text": "2. Sony a6700 Product Page"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://electronics.sony.com/imaging/interchangeable-lens-cameras/aps-c/p/ilce6700-b"
          }
        }
      },
      "children": []
    },
    "source_om_system": {
      "type": "Text",
      "props": {
        "text": "3. OM System OM-5 Overview"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://explore.omsystem.com/us/en/om-5"
          }
        }
      },
      "children": []
    }
  }
}
